1	import { describe, it, expect, vi } from "vitest";
2	import { screen } from "@testing-library/react";
3	import userEvent from "@testing-library/user-event";
4	import { axe } from "jest-axe";
5	import { renderWithProviders } from "./helpers";
6	
7	const resolveReport = vi.fn(async () => ({ ok: true }));
8	const setUserSuspended = vi.fn(async () => ({ ok: true }));
9	vi.mock("@/app/(admin)/admin/actions", () => ({
10	  resolveReport: (...a: unknown[]) => resolveReport(...(a as [])),
11	  setUserSuspended: (...a: unknown[]) => setUserSuspended(...(a as [])),
12	}));
13	
14	import { ReportCard } from "@/components/admin/ReportCard";
15	import { UsersTable } from "@/components/admin/UsersTable";
16	
17	const REPORT = {
18	  id: "r1",
19	  reason: "The caller was hostile.",
20	  status: "open" as const,
21	  whenLabel: "Jun 8, 2026",
22	  reporterName: "Walter",
23	  targetId: "c1",
24	  targetName: "Casey",
25	};
26	
27	describe("ReportCard", () => {
28	  it("shows the report and actions with no a11y violations", async () => {
29	    const { container } = renderWithProviders(
30	      <ul>
31	        <ReportCard report={REPORT} />
32	      </ul>,
33	    );
34	    expect(screen.getByText(/the caller was hostile/i)).toBeInTheDocument();
35	    expect(screen.getByText(/from: walter/i)).toBeInTheDocument();
36	    expect(await axe(container)).toHaveNoViolations();
37	  });
38	
39	  it("marks reviewed and suspends the target", async () => {
40	    const user = userEvent.setup();
41	    renderWithProviders(
42	      <ul>
43	        <ReportCard report={REPORT} />
44	      </ul>,
45	    );
46	    await user.click(screen.getByRole("button", { name: /mark reviewed/i }));
47	    expect(resolveReport).toHaveBeenCalledWith("r1");
48	    await user.click(screen.getByRole("button", { name: /suspend the reported user/i }));
49	    expect(setUserSuspended).toHaveBeenCalledWith({ userId: "c1", suspended: true });
50	  });
51	});
52	
53	describe("UsersTable", () => {
54	  const rows = [
55	    { id: "u1", name: "Casey", email: "casey@x.com", role: "customer" as const, suspended: false },
56	    { id: "u2", name: "Maya", email: "maya@x.com", role: "provider" as const, suspended: true },
57	    { id: "u3", name: "Avery", email: "admin@x.com", role: "admin" as const, suspended: false },
58	  ];
59	
60	  it("renders a semantic table; admins have no suspend action; no a11y violations", async () => {
61	    const { container } = renderWithProviders(<UsersTable rows={rows} />);
62	    expect(screen.getByRole("table", { name: /customers and listeners/i })).toBeInTheDocument();
63	    // 2 actionable users (customer + provider); admin row shows no button.
64	    // Accessible names carry the subject so each row's action is unambiguous.
65	    expect(screen.getByRole("button", { name: /suspend casey/i })).toBeInTheDocument();
66	    expect(screen.getByRole("button", { name: /reinstate maya/i })).toBeInTheDocument();
67	    expect(await axe(container)).toHaveNoViolations();
68	  });
69	
70	  it("suspends an active user", async () => {
71	    const user = userEvent.setup();
72	    renderWithProviders(<UsersTable rows={rows} />);
73	    await user.click(screen.getByRole("button", { name: /suspend casey/i }));
74	    expect(setUserSuspended).toHaveBeenCalledWith({ userId: "u1", suspended: true });
75	  });
76	});
